// ═══ CASE 1: execute() — exception to UncaughtExceptionHandler ═══
pool.execute(() -> {
    throw new RuntimeException("Settlement crashed!");
    // Exception goes to UncaughtExceptionHandler
    // Worker thread DIES — pool creates replacement
    // Default handler: prints to stderr (may be lost in production!)
});

// Set custom handler:
Thread.setDefaultUncaughtExceptionHandler((thread, ex) -> {
    log.error("Thread {} crashed: {}", thread.getName(), ex.getMessage(), ex);
    alertOps("Thread crash: " + ex.getMessage());
});

// ═══ CASE 2: submit() — exception captured in Future ═══
Future<?> future = pool.submit(() -> {
    throw new RuntimeException("Settlement crashed!");
    // Exception CAPTURED in Future! Worker thread survives!
});
// future.get() → throws ExecutionException(cause=RuntimeException)
// If you NEVER call future.get() → exception SILENTLY LOST!

try {
    future.get();  // MUST call to surface the exception!
} catch (ExecutionException e) {
    log.error("Task failed: {}", e.getCause().getMessage(), e.getCause());
}

// ═══ CASE 3: afterExecute() — catch ALL exceptions ═══
ThreadPoolExecutor pool = new ThreadPoolExecutor(4, 4, 0, TimeUnit.SECONDS,
    new LinkedBlockingQueue<>()) {
    @Override
    protected void afterExecute(Runnable r, Throwable t) {
        super.afterExecute(r, t);
        // For execute(): throwable is the exception
        if (t != null) {
            log.error("Task exception (execute): {}", t.getMessage(), t);
        }
        // For submit(): throwable is null, exception inside FutureTask
        if (t == null && r instanceof Future<?> f) {
            try {
                if (f.isDone()) f.get();  // extracts exception from Future!
            } catch (ExecutionException e) {
                log.error("Task exception (submit): {}", e.getCause().getMessage(), e.getCause());
            } catch (Exception e) { /* interrupted/cancelled */ }
        }
    }
};
