package com.bank.threadex;

import org.junit.jupiter.api.Test;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import static org.assertj.core.api.Assertions.*;

class ThreadExceptionTest {

    // ═══ submit() captures exception in Future ═══
    @Test
    void submit_capturesException_inFuture() {
        ExecutorService pool = Executors.newFixedThreadPool(1);
        Future<?> future = pool.submit(() -> {
            throw new RuntimeException("NPE in settlement!");
        });

        // Exception ONLY surfaces when get() is called:
        assertThatThrownBy(future::get)
            .isInstanceOf(ExecutionException.class)
            .hasCauseInstanceOf(RuntimeException.class)
            .hasRootCauseMessage("NPE in settlement!");

        pool.shutdown();
    }

    // ═══ submit() without get() — exception SILENTLY LOST! ═══
    @Test
    void submit_withoutGet_exceptionLost() throws InterruptedException {
        ExecutorService pool = Executors.newFixedThreadPool(1);
        AtomicBoolean exceptionLogged = new AtomicBoolean(false);

        pool.submit(() -> {
            throw new RuntimeException("Silent failure!");
            // Nobody calls future.get() → this exception is LOST!
        });

        Thread.sleep(200);
        // No exception visible! No log! No alert! SILENT!
        assertThat(exceptionLogged.get()).isFalse();
        pool.shutdown();
    }

    // ═══ UncaughtExceptionHandler — catches execute() exceptions ═══
    @Test
    void uncaughtExceptionHandler_catchesExecute() throws InterruptedException {
        AtomicReference<String> caughtMessage = new AtomicReference<>();
        CountDownLatch caught = new CountDownLatch(1);

        ThreadFactory factory = r -> {
            Thread t = new Thread(r);
            t.setUncaughtExceptionHandler((thread, ex) -> {
                caughtMessage.set(ex.getMessage());
                caught.countDown();
            });
            return t;
        };

        ExecutorService pool = new ThreadPoolExecutor(1, 1, 0, TimeUnit.SECONDS,
            new LinkedBlockingQueue<>(), factory);

        pool.execute(() -> { throw new RuntimeException("Debit failed!"); });

        caught.await(5, TimeUnit.SECONDS);
        assertThat(caughtMessage.get()).isEqualTo("Debit failed!");
        pool.shutdown();
    }

    // ═══ afterExecute() — catches ALL exceptions ═══
    @Test
    void afterExecute_catchesAll() throws InterruptedException {
        AtomicReference<String> caughtMessage = new AtomicReference<>();
        CountDownLatch caught = new CountDownLatch(1);

        ThreadPoolExecutor pool = new ThreadPoolExecutor(1, 1, 0, TimeUnit.SECONDS,
            new LinkedBlockingQueue<>()) {
            @Override
            protected void afterExecute(Runnable r, Throwable t) {
                super.afterExecute(r, t);
                if (t == null && r instanceof Future<?> f) {
                    try { if (f.isDone()) f.get(); }
                    catch (ExecutionException e) {
                        caughtMessage.set(e.getCause().getMessage());
                        caught.countDown();
                    } catch (Exception ignored) { }
                }
                if (t != null) {
                    caughtMessage.set(t.getMessage());
                    caught.countDown();
                }
            }
        };

        pool.submit(() -> { throw new RuntimeException("Settlement NPE!"); });

        caught.await(5, TimeUnit.SECONDS);
        assertThat(caughtMessage.get()).isEqualTo("Settlement NPE!");
        pool.shutdown();
    }
}
